WITH with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM transactions), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(CASE WHEN merchant = '7-Eleven' THEN burst_id ELSE 0 END) AS 7_eleven_burst_id, COUNT(*) FILTER (WHERE txn_type = 'CREDIT') AS credit_rows, SUM(burst_id) AS total_burst_id, COUNT(*) FILTER (WHERE txn_type = 'CREDIT') AS credit_rows_2, SUM(CASE WHEN txn_type = 'CREDIT' THEN burst_id ELSE 0 END) AS credit_burst_id FROM islands GROUP BY 1;
